#!/bin/bash
# pod: V12 (explicit signatures) vs V11 — compile time + specialisation count, node-identical search on 12 positions, battery.
set -u; cd ~/chess; V=~/chess/venv/bin/python
FENS=("r1bq1rk1/pp2bppp/2n1pn2/3p4/2PP4/2N2N2/PP2BPPP/R2QKB1R w KQ - 4 9" "r4rk1/1pqbbppp/p3pn2/8/PP1Q4/2N1P3/1B2BPPP/R2R2K1 b - - 2 14" "8/8/8/8/5pk1/3R4/4r3/6K1 b - - 33 66" "7k/8/8/8/8/1R6/7r/2K5 w - - 24 125" "rnbqkb1r/pp3ppp/2n1pn2/2p5/3P4/2N1PN2/PP2BPPP/R1BQK2R b KQkq - 3 7" "r3k2r/pppq1ppp/2n2n2/3pp3/3PP3/2N2N2/PPPQ1PPP/R3K2R w KQkq - 4 9" "rnbqk2r/ppp1bppp/4pn2/3p4/2P5/1P3NP1/P2PPPBP/RNBQK2R b KQkq - 0 5" "r2qkb1r/pp2pppp/2n2n2/3p4/3P1Bb1/1QPB4/PP3PPP/RN2K1NR b KQkq - 4 7" "8/P6k/8/8/8/8/8/K7 w - - 0 1" "rnbqkbnr/ppp1p1pp/8/3pPp2/8/8/PPPP1PPP/RNBQKBNR w KQkq f6 0 3" "6k1/5ppp/8/8/8/8/5PPP/3R2K1 w - - 0 1" "r1bqkb1r/1p3ppp/p3pn2/2p5/2BP4/2N1PN2/PP3PPP/R1BQ1RK1 b kq - 1 7")
for D in ship_v85_v11 ship_v85_v12; do echo "=== $D: census ==="; (cd $D && BINI_JOIN_S=150 nice -n 5 $V ~/chess/sig_detail.py 2>&1 | grep -v "^bini-5.0" | head -3); echo "=== $D: fixed-node search (300k) ==="; (cd $D && nice -n 5 $V ~/chess/search_probe.py ~/chess/$D 300000 "${FENS[@]}" 2>&1 | grep -v "^bini-5.0\|WARN\|compiled" | tee ~/chess/gates/identity_$D.txt); done
echo "=== identity diff (empty = node-identical) ==="; diff gates/identity_ship_v85_v11.txt gates/identity_ship_v85_v12.txt && echo "IDENTICAL on all 12 positions"
echo "=== battery on V12 ==="; (cd ship_v85_v12 && cp ~/chess/fen_battery.py . && env -u BINI_JOIN_S nice -n 5 $V fen_battery.py 2>&1 | grep "BAD\|BATTERY\|^import")
